export const LEGEND_HUB_ICONS=[new URL('../../assets/gr-legend-hub-1-original.png',import.meta.url).href,new URL('../../assets/gr-legend-hub-2-original.png',import.meta.url).href];
function openDialog(owner,title,render){ensureLegendHubStyle(owner);owner.__legendConfig?.close();owner.__legendConfig?.remove();const dialog=document.createElement('dialog');dialog.className='lh-dialog';dialog.setAttribute('aria-label',title);dialog.innerHTML='<header><h3></h3><button type="button" data-lh-close></button></header><div class="lh-form"></div>';dialog.querySelector('h3').textContent=title;const close=dialog.querySelector('[data-lh-close]');close.textContent='×';close.setAttribute('aria-label',owner._t('weather.legend.close'));close.onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();if(owner.__legendConfig===dialog)owner.__legendConfig=null;owner.__legendOpener?.focus?.();});owner.shadow.append(dialog);owner.__legendConfig=dialog;render(dialog.querySelector('.lh-form'));dialog.showModal();return dialog;}
const select=(label,key,values,current,labels=v=>v)=>`<label><span>${esc(label)}</span><select data-lh-key="${key}">${values.map(v=>`<option value="${v}" ${current===v?'selected':''}>${esc(labels(v))}</option>`).join('')}</select></label>`;
const check=(label,key,value)=>`<label><span>${esc(label)}</span><input type="checkbox" data-lh-key="${key}" ${value?'checked':''}></label>`;
export function openLegendConfig(owner,id){const t=k=>legendText(owner,k);openDialog(owner,t('configure')+' · '+legendTitle(owner,id),form=>{
 const render=()=>{const c={...legendOptions(owner,id),...(id==='precipitation'?{mode:({auto:'inherit',on:'on',off:'off'})[owner._weatherDisplayLegendMode()]}:{})},p=c.orientation==='vertical'?'v_':'h_',focus=form.querySelector(':focus')?.dataset.lhKey;form.innerHTML=select(t('presentation'),'presentation',LEGEND_OPTIONS.presentation,c.presentation,t)+select(t('orientation'),'orientation',LEGEND_OPTIONS.orientation,c.orientation,t)+select(t('size'),'size',LEGEND_OPTIONS.size,c.size)+select(t('density'),'density',LEGEND_OPTIONS.density,c.density,t)+select(t('style'),'style',LEGEND_OPTIONS.style,c.style,t)+select(t('material'),'material',LEGEND_OPTIONS.material,c.material,t)+select(t('labels'),'labels',LEGEND_OPTIONS.labels,c.labels,v=>t(p+v))+select(t('ticks'),'ticks',LEGEND_OPTIONS.ticks,c.ticks,v=>t(p+v))+select(t('foreground'),'foreground',LEGEND_OPTIONS.foreground,c.foreground,t)+check(t('autoInvert'),'autoInvert',c.autoInvert)+check(t('shadow'),'shadow',c.shadow)+check(t('outline'),'outline',c.outline)+select(owner._t('weather.legend.view'),'mode',LEGEND_OPTIONS.mode,c.mode,v=>v==='inherit'?t(v):owner._t('weather.layer.'+v))+'<div class="lh-preview"></div>';const model=legendDescriptor(owner,id);if(model)form.querySelector('.lh-preview').append(renderLegendScale(model,c,Math.min(430,form.clientWidth||280)));if(id==='synoptic'||id==='other'&&!(owner._weatherLegendActiveModels?.()||[]).some(m=>!['precipitation','snow'].includes(m.family)&&m.entries.length)){for(const key of ['density','style','material','labels','ticks'])form.querySelector('[data-lh-key='+key+']').disabled=true;const note=document.createElement('p');note.textContent=t('categorical');form.querySelector('.lh-preview').append(note);}if(focus)form.querySelector(`[data-lh-key="${focus}"]`)?.focus();};
 render();form.addEventListener('change',event=>{const input=event.target,key=input.dataset.lhKey;if(!key)return;patchLegend(owner,id,{[key]:input.type==='checkbox'?input.checked:input.value});render();});
 });}
export function openHubConfig(owner){const t=k=>legendText(owner,k);openDialog(owner,t('title')+' · '+t('settings'),form=>{
 let dragging=null;
 const render=()=>{const c=legendHubState(owner).config,entries=legendEntries(owner);form.innerHTML=`<div class="lh-symbols">${LEGEND_HUB_ICONS.map((src,i)=>`<button type="button" data-lh-icon="${i+1}" aria-label="${esc(t('icon'))} ${i+1}" aria-pressed="${c.icon===i+1}"><img src="${src}" alt=""></button>`).join('')}</div>`+select(t('slots'),'count',Array.from({length:12},(_,i)=>String(i+1)),String(c.slots.length))+select(t('direction'),'direction',['dynamic','left','right','up','down','horizontal','vertical'],c.direction,t)+check(t('autoClose'),'autoClose',c.autoClose)+`<div class="lh-slot-editor">${c.slots.map((id,i)=>`<div class="lh-slot-row" draggable="true" data-lh-row="${i}"><span draggable="true">${i+1}</span><select data-lh-slot="${i}" aria-label="${esc(t('slots'))} ${i+1}"><option value="">${esc(t('empty'))}</option>${entries.map(e=>`<option value="${e.id}" ${id===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select><button type="button" data-lh-move="${i}" data-delta="-1" aria-label="${esc(t('move'))} ${i+1} ↑" ${i===0?'disabled':''}>↑</button><button type="button" data-lh-move="${i}" data-delta="1" aria-label="${esc(t('move'))} ${i+1} ↓" ${i===c.slots.length-1?'disabled':''}>↓</button></div>`).join('')}</div>`;};
 const move=(from,to)=>{const c=legendHubState(owner).config,slots=[...c.slots];if(from===to||from<0||to<0||to>=slots.length)return;[slots[from],slots[to]]=[slots[to],slots[from]];saveLegendHub(owner,{slots});render();};
 render();form.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.lhIcon){saveLegendHub(owner,{icon:Number(b.dataset.lhIcon)});render();}if(b.dataset.lhMove!==undefined)move(Number(b.dataset.lhMove),Number(b.dataset.lhMove)+Number(b.dataset.delta));});
 form.addEventListener('change',event=>{const input=event.target,c=legendHubState(owner).config;if(input.dataset.lhSlot!==undefined)saveLegendHub(owner,assignLegendSlot(c,Number(input.dataset.lhSlot),input.value||null));else if(input.dataset.lhKey==='count')saveLegendHub(owner,{slots:Array.from({length:Number(input.value)},(_,i)=>c.slots[i]||null)});else if(input.dataset.lhKey)saveLegendHub(owner,{[input.dataset.lhKey]:input.type==='checkbox'?input.checked:input.value});render();});
 form.addEventListener('dragstart',event=>{dragging=Number(event.target.closest('[data-lh-row]')?.dataset.lhRow);event.dataTransfer?.setData('text/plain',String(dragging));});form.addEventListener('dragover',event=>{if(event.target.closest('[data-lh-row]'))event.preventDefault();});form.addEventListener('drop',event=>{const row=event.target.closest('[data-lh-row]');if(row&&Number.isInteger(dragging)){event.preventDefault();move(dragging,Number(row.dataset.lhRow));}dragging=null;});
 });}
export function decorateLegend(owner,id,host){ensureLegendHubStyle(owner);const c=legendOptions(owner,id),ink=legendInk('#0b1520',c.foreground,c.autoInvert);host.style.setProperty('--lh-category-ink',ink.color);host.style.setProperty('--lh-category-shadow',c.shadow?'0 1px 3px #000':'none');host.style.setProperty('--lh-category-outline',c.outline?'.25px '+(ink.color==='#111318'?'#ffffff88':'#00000088'):'0px transparent');host.classList.add('lh-window');host.dataset.presentation=c.presentation;host.dataset.orientation=c.orientation;host.style.setProperty('--lh-category-size',({S:20,M:24,L:28,XL:32})[c.size]+'px');host.style.setProperty('--lh-width',c.orientation==='vertical'?'260px':({S:260,M:304,L:384,XL:464})[c.size]+'px');let button=host.querySelector('[data-lh-config]');if(!button){button=document.createElement('button');button.type='button';button.dataset.lhConfig=id;button.className='lh-config-button';button.textContent='⚙';host.querySelector('.gr-legend-actions')?.prepend(button);button.onclick=event=>{event.stopPropagation();owner.__legendOpener=button;openLegendConfig(owner,id);};host.tabIndex=0;const raise=()=>{for(const other of owner.shadow.querySelectorAll('.lh-active-window'))if(other!==host)other.classList.remove('lh-active-window');host.classList.add('lh-active-window');};host.addEventListener('focusin',raise);host.addEventListener('pointerdown',raise,{capture:true});host.addEventListener('keydown',event=>{if(event.key==='F2'||event.shiftKey&&event.key==='F10'){event.preventDefault();openLegendConfig(owner,id);}});host.addEventListener('contextmenu',event=>{event.preventDefault();openLegendConfig(owner,id);});let hold=null;host.addEventListener('pointerdown',event=>{if(event.target.closest('button,select,summary')||!event.target.closest('.lh-scale'))return;hold={id:event.pointerId,x:event.clientX,y:event.clientY,timer:setTimeout(()=>{hold=null;openLegendConfig(owner,id);},600)};});const cancel=()=>{clearTimeout(hold?.timer);hold=null;};host.addEventListener('pointermove',event=>{if(hold&&Math.hypot(event.clientX-hold.x,event.clientY-hold.y)>8)cancel();});for(const type of ['pointerup','pointercancel','lostpointercapture'])host.addEventListener(type,cancel);}
 button.setAttribute('aria-label',legendText(owner,'configure'));return c;
}
